#nullable enable // autogenerated

using MVZ2.GameContent.Damages;
using MVZ2.GameContent.Models;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Models;
using MVZ2.Vanilla.Properties;
using MVZ2Logic.Models;
using PVZEngine.Buffs;
using PVZEngine.Damages;
using PVZEngine.Definitions;

namespace MVZ2.GameContent.Buffs.Enemies
{
    [AutoBuffDefinition(VanillaBuffNames.Enemy.poisoned)]
    public class PoisonedBuff : BuffDefinition
    {
        public PoisonedBuff(string nsp, string name) : base(nsp, name)
        {
            AddModelInsertion(LogicModelHelper.ANCHOR_CENTER, VanillaModelKeys.poisonParticles, VanillaModelID.poisonParticles);
        }
        public override void PostUpdate(Buff buff)
        {
            base.PostUpdate(buff);

            var entity = buff.GetEntity();
            if (entity != null)
            {
                DamageEffectList damageEffectList = new DamageEffectList(VanillaDamageEffects.MUTE, VanillaDamageEffects.POISON);
                if (entity.Health > 20)
                {
                    entity.TakeDamageNoSource(WITHER_DAMAGE, damageEffectList);
                }
            }

            var timeout = buff.GetProperty<int>(PROP_TIMEOUT);
            timeout--;
            buff.SetProperty(PROP_TIMEOUT, timeout);
            if (timeout <= 0)
            {
                buff.Remove();
            }
        }
        public static readonly VanillaBuffPropertyMeta<int> PROP_TIMEOUT = new VanillaBuffPropertyMeta<int>("Timeout");
        public const float WITHER_DAMAGE = 1f;
        public const float WITHER_DAMAGE_ARMOR = 3f;
    }
}
